import{_ as n,c as a,o as h,a2 as e}from"./chunks/framework.B7el9cAC.js";const p=JSON.parse('{"title":"Mục 2.5 – Internet và Dịch Vụ Internet","description":"","frontmatter":{},"headers":[],"relativePath":"chuong-2/2.5-internet-dich-vu.md","filePath":"chuong-2/2.5-internet-dich-vu.md","lastUpdated":1775298974000}'),i={name:"chuong-2/2.5-internet-dich-vu.md"};function o(s,t,r,d,c,g){return h(),a("div",null,[...t[0]||(t[0]=[e(`<h1 id="muc-2-5-–-internet-va-dich-vu-internet" tabindex="-1">Mục 2.5 – Internet và Dịch Vụ Internet <a class="header-anchor" href="#muc-2-5-–-internet-va-dich-vu-internet" aria-label="Permalink to &quot;Mục 2.5 – Internet và Dịch Vụ Internet&quot;">​</a></h1><blockquote><p><strong>Chương 2: Mạng máy tính và Internet</strong></p></blockquote><hr><h2 id="🔹-1-gioi-thieu-sieu-co-ban" tabindex="-1">🔹 1. GIỚI THIỆU SIÊU CƠ BẢN <a class="header-anchor" href="#🔹-1-gioi-thieu-sieu-co-ban" aria-label="Permalink to &quot;🔹 1. GIỚI THIỆU SIÊU CƠ BẢN&quot;">​</a></h2><h3 id="internet-la-gi-va-tu-đau-đen" tabindex="-1">Internet là gì và từ đâu đến? <a class="header-anchor" href="#internet-la-gi-va-tu-đau-đen" aria-label="Permalink to &quot;Internet là gì và từ đâu đến?&quot;">​</a></h3><p>Hãy tưởng tượng thế giới như một thành phố khổng lồ với hàng tỷ ngôi nhà. Mỗi ngôi nhà là một máy tính. <strong>Internet</strong> chính là hệ thống đường giao thông nối tất cả các ngôi nhà đó lại với nhau – bất kể bạn ở Việt Nam hay Mỹ, bất kể máy tính bạn là PC hay điện thoại.</p><p>Internet không thuộc sở hữu của bất kỳ ai và không có &quot;trung tâm điều khiển&quot;. Nó là <strong>mạng của các mạng</strong> – hàng triệu mạng nhỏ (LAN, WAN của công ty, trường học, nhà cung cấp dịch vụ...) kết nối lại với nhau thông qua giao thức TCP/IP.</p><p><strong>Một số dịch vụ chạy trên Internet:</strong></p><ul><li>Bạn lướt web → dùng dịch vụ <strong>WWW (World Wide Web)</strong></li><li>Bạn gửi email → dùng dịch vụ <strong>Email</strong></li><li>Bạn tải file → dùng dịch vụ <strong>FTP</strong></li><li>Bạn chat realtime → dùng dịch vụ <strong>Instant Messaging / VoIP</strong></li></ul><hr><h2 id="🔹-2-ly-thuyet-chi-tiet" tabindex="-1">🔹 2. LÝ THUYẾT CHI TIẾT <a class="header-anchor" href="#🔹-2-ly-thuyet-chi-tiet" aria-label="Permalink to &quot;🔹 2. LÝ THUYẾT CHI TIẾT&quot;">​</a></h2><h3 id="_2-1-internet-la-gi" tabindex="-1">2.1 Internet là gì? <a class="header-anchor" href="#_2-1-internet-la-gi" aria-label="Permalink to &quot;2.1 Internet là gì?&quot;">​</a></h3><p><strong>Internet (International Network)</strong> là hệ thống <strong>mạng máy tính toàn cầu</strong> kết nối hàng tỷ thiết bị với nhau thông qua bộ giao thức <strong>TCP/IP</strong>.</p><ul><li>Hình thành từ mạng ARPANET (Bộ Quốc phòng Mỹ, 1969) – ban đầu phục vụ quân sự và nghiên cứu.</li><li>Mở rộng ra toàn thế giới vào những năm 1990 khi Tim Berners-Lee phát minh ra <strong>WWW</strong>.</li><li>Hiện nay kết nối hơn <strong>5 tỷ người dùng</strong> trên toàn thế giới.</li><li>Được kết nối vật lý qua hệ thống cáp biển, vệ tinh, và cáp quang trên đất liền.</li></ul><h3 id="_2-2-world-wide-web-www" tabindex="-1">2.2 World Wide Web (WWW) <a class="header-anchor" href="#_2-2-world-wide-web-www" aria-label="Permalink to &quot;2.2 World Wide Web (WWW)&quot;">​</a></h3><p><strong>WWW (World Wide Web)</strong> là hệ thống tài liệu siêu văn bản (hypertext) liên kết với nhau, được truy cập qua Internet bằng trình duyệt web.</p><blockquote><p>⚠️ <strong>Lưu ý quan trọng:</strong> WWW <strong>không phải là Internet</strong>. WWW là <strong>một dịch vụ chạy trên Internet</strong> – cũng như email hay FTP là các dịch vụ khác.</p></blockquote><p><strong>Các thành phần của WWW:</strong></p><table tabindex="0"><thead><tr><th>Thành phần</th><th>Giải thích</th></tr></thead><tbody><tr><td><strong>URL</strong></td><td>Địa chỉ tài nguyên trên web: <code>https://www.google.com/search</code></td></tr><tr><td><strong>HTTP/HTTPS</strong></td><td>Giao thức truyền tải trang web</td></tr><tr><td><strong>HTML</strong></td><td>Ngôn ngữ đánh dấu xây dựng trang web</td></tr><tr><td><strong>Web Browser</strong></td><td>Phần mềm hiển thị trang web (Chrome, Firefox...)</td></tr><tr><td><strong>Web Server</strong></td><td>Máy chủ lưu trữ và phục vụ trang web</td></tr></tbody></table><p><strong>Giao thức HTTP vs HTTPS:</strong></p><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>HTTP</th><th>HTTPS</th></tr></thead><tbody><tr><td><strong>Viết tắt</strong></td><td>HyperText Transfer Protocol</td><td>HTTP Secure</td></tr><tr><td><strong>Mã hóa</strong></td><td>Không</td><td>Có (SSL/TLS)</td></tr><tr><td><strong>Cổng mặc định</strong></td><td>80</td><td>443</td></tr><tr><td><strong>Biểu tượng trình duyệt</strong></td><td>⚠️ &quot;Không an toàn&quot;</td><td>🔒 Khóa xanh</td></tr><tr><td><strong>Dùng cho</strong></td><td>Website thông thường cũ</td><td>Mọi website hiện đại, ngân hàng, mua sắm</td></tr></tbody></table><h3 id="_2-3-ten-mien-domain-name-va-dns" tabindex="-1">2.3 Tên miền (Domain Name) và DNS <a class="header-anchor" href="#_2-3-ten-mien-domain-name-va-dns" aria-label="Permalink to &quot;2.3 Tên miền (Domain Name) và DNS&quot;">​</a></h3><h4 id="ten-mien-la-gi" tabindex="-1">Tên miền là gì? <a class="header-anchor" href="#ten-mien-la-gi" aria-label="Permalink to &quot;Tên miền là gì?&quot;">​</a></h4><p><strong>Tên miền (Domain Name)</strong> là địa chỉ dễ nhớ để trỏ đến máy chủ web, thay vì phải nhớ địa chỉ IP dạng số.</p><p><strong>Ví dụ:</strong></p><ul><li>Thay vì nhớ địa chỉ IP số của Google, bạn chỉ cần nhớ <code>google.com</code></li><li>Thay vì nhớ địa chỉ IP số của VnExpress, bạn chỉ cần nhớ <code>vnexpress.net</code></li></ul><blockquote><p><em>(Địa chỉ IP cụ thể của các trang web có thể thay đổi theo thời gian – điều quan trọng là tên miền luôn ổn định cho dù IP thay đổi.)</em></p></blockquote><p><strong>Cấu trúc tên miền:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://  www  .  google  .  com  /  search  ?  q=tin+hoc</span></span>
<span class="line"><span> Giao      ──   Tên miền    Tên   ──  Đường   ──  Tham số</span></span>
<span class="line"><span> thức    phụ   cấp hai     miền     dẫn       truy vấn</span></span>
<span class="line"><span>              (sub)        cấp</span></span>
<span class="line"><span>                           cao</span></span></code></pre></div><p><strong>Các loại tên miền cấp cao (TLD – Top Level Domain):</strong></p><table tabindex="0"><thead><tr><th>TLD</th><th>Ý nghĩa</th><th>Ví dụ</th></tr></thead><tbody><tr><td><code>.com</code></td><td>Thương mại (commercial)</td><td>google.com, facebook.com</td></tr><tr><td><code>.edu</code></td><td>Giáo dục (education)</td><td>mit.edu, hust.edu.vn</td></tr><tr><td><code>.gov</code></td><td>Chính phủ (government)</td><td>whitehouse.gov, chinhphu.vn</td></tr><tr><td><code>.org</code></td><td>Tổ chức phi lợi nhuận</td><td>wikipedia.org</td></tr><tr><td><code>.net</code></td><td>Mạng lưới (network)</td><td>speedtest.net</td></tr><tr><td><code>.vn</code></td><td>Việt Nam (country code)</td><td>vnexpress.net, moet.gov.vn</td></tr></tbody></table><h4 id="dns-la-gi" tabindex="-1">DNS là gì? <a class="header-anchor" href="#dns-la-gi" aria-label="Permalink to &quot;DNS là gì?&quot;">​</a></h4><p><strong>DNS (Domain Name System)</strong> là hệ thống <strong>dịch tên miền sang địa chỉ IP</strong> và ngược lại.</p><p>DNS hoạt động như <strong>danh bạ điện thoại của Internet</strong> – bạn tra tên người → DNS trả về số điện thoại (địa chỉ IP).</p><p><strong>Quá trình phân giải DNS:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Bạn gõ: www.google.com</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>[Trình duyệt] → Kiểm tra cache (đã biết IP chưa?)</span></span>
<span class="line"><span>        ↓ Chưa biết</span></span>
<span class="line"><span>[DNS Resolver] → Hỏi DNS Server của ISP</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>[DNS Server ISP] → Hỏi Root DNS Server (.com)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>[Root DNS] → Chuyển đến DNS của Google</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>[DNS Google] → Trả về IP: 142.250.196.46</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>[Trình duyệt] → Kết nối đến IP 142.250.196.46</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Trang Google hiện ra!</span></span></code></pre></div><h3 id="_2-4-email-va-cac-giao-thuc-email" tabindex="-1">2.4 Email và các giao thức email <a class="header-anchor" href="#_2-4-email-va-cac-giao-thuc-email" aria-label="Permalink to &quot;2.4 Email và các giao thức email&quot;">​</a></h3><p><strong>Email (Electronic Mail)</strong> là dịch vụ gửi và nhận thư điện tử qua Internet.</p><p><strong>Cấu trúc địa chỉ email:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nguyenvana  @  gmail  .  com</span></span>
<span class="line"><span>   ────────    ──────    ───</span></span>
<span class="line"><span>  Tên người    Tên nhà   TLD</span></span>
<span class="line"><span>   dùng        cung cấp</span></span></code></pre></div><p><strong>Các giao thức email:</strong></p><table tabindex="0"><thead><tr><th>Giao thức</th><th>Viết tắt</th><th>Cổng</th><th>Chức năng</th></tr></thead><tbody><tr><td><strong>SMTP</strong></td><td>Simple Mail Transfer Protocol</td><td>25 (587 có TLS)</td><td><strong>Gửi</strong> email từ máy khách → máy chủ, và giữa các máy chủ</td></tr><tr><td><strong>POP3</strong></td><td>Post Office Protocol v3</td><td>110 (995 có SSL)</td><td><strong>Nhận</strong> email – tải về máy và xóa khỏi server</td></tr><tr><td><strong>IMAP</strong></td><td>Internet Message Access Protocol</td><td>143 (993 có SSL)</td><td><strong>Nhận</strong> email – đồng bộ với server, truy cập từ nhiều thiết bị</td></tr></tbody></table><blockquote><p><strong>Nhớ đơn giản:</strong> SMTP = <strong>Gửi</strong>, POP3/IMAP = <strong>Nhận</strong><strong>POP3 vs IMAP:</strong> POP3 tải về máy và xóa server → chỉ dùng được 1 thiết bị. IMAP đồng bộ với server → dùng nhiều thiết bị (điện thoại, máy tính, tablet cùng thấy hộp thư).</p></blockquote><h3 id="_2-5-ftp-–-truyen-file-qua-mang" tabindex="-1">2.5 FTP – Truyền file qua mạng <a class="header-anchor" href="#_2-5-ftp-–-truyen-file-qua-mang" aria-label="Permalink to &quot;2.5 FTP – Truyền file qua mạng&quot;">​</a></h3><p><strong>FTP (File Transfer Protocol)</strong> là giao thức dùng để <strong>tải lên (upload) hoặc tải xuống (download) file</strong> từ/lên máy chủ qua mạng.</p><ul><li>Dùng cổng <strong>21</strong> (FTP) và <strong>20</strong> (truyền dữ liệu thực tế).</li><li><strong>FTPS</strong> và <strong>SFTP</strong> là phiên bản bảo mật của FTP (có mã hóa).</li><li>Ngày nay, FTP dần được thay thế bởi HTTPS và các dịch vụ lưu trữ đám mây (Google Drive, OneDrive...).</li></ul><p><strong>Ứng dụng thực tế:</strong></p><ul><li>Web developer dùng FTP/SFTP để upload file HTML, CSS, PHP lên hosting.</li><li>Công ty dùng FTP server nội bộ để chia sẻ file lớn.</li></ul><h3 id="_2-6-cac-dich-vu-internet-khac" tabindex="-1">2.6 Các dịch vụ Internet khác <a class="header-anchor" href="#_2-6-cac-dich-vu-internet-khac" aria-label="Permalink to &quot;2.6 Các dịch vụ Internet khác&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Dịch vụ</th><th>Giao thức</th><th>Chức năng</th><th>Ví dụ</th></tr></thead><tbody><tr><td><strong>Truy cập web</strong></td><td>HTTP/HTTPS</td><td>Xem trang web</td><td>Google, Facebook, Zalo Web</td></tr><tr><td><strong>Email</strong></td><td>SMTP/POP3/IMAP</td><td>Gửi nhận thư điện tử</td><td>Gmail, Outlook, Yahoo Mail</td></tr><tr><td><strong>Chat/Nhắn tin</strong></td><td>XMPP, WebSocket</td><td>Nhắn tin thời gian thực</td><td>Messenger, Zalo, Telegram</td></tr><tr><td><strong>Gọi video</strong></td><td>RTP/WebRTC</td><td>Gọi điện/video call</td><td>Zoom, Google Meet, Skype</td></tr><tr><td><strong>Truyền file</strong></td><td>FTP/SFTP</td><td>Upload/download file</td><td>FileZilla, WinSCP</td></tr><tr><td><strong>Điều khiển từ xa</strong></td><td>SSH, RDP</td><td>Điều khiển máy tính từ xa</td><td>PuTTY, Remote Desktop</td></tr><tr><td><strong>Streaming</strong></td><td>HLS, RTMP</td><td>Phát video trực tiếp</td><td>YouTube, Netflix, TikTok</td></tr><tr><td><strong>DNS</strong></td><td>DNS</td><td>Phân giải tên miền → IP</td><td>Google DNS (8.8.8.8)</td></tr></tbody></table><hr><h2 id="🔹-3-giai-thich-ban-chat" tabindex="-1">🔹 3. GIẢI THÍCH BẢN CHẤT <a class="header-anchor" href="#🔹-3-giai-thich-ban-chat" aria-label="Permalink to &quot;🔹 3. GIẢI THÍCH BẢN CHẤT&quot;">​</a></h2><h3 id="internet-www" tabindex="-1">Internet ≠ WWW <a class="header-anchor" href="#internet-www" aria-label="Permalink to &quot;Internet ≠ WWW&quot;">​</a></h3><p>Đây là nhầm lẫn rất phổ biến, kể cả với người lớn:</p><table tabindex="0"><thead><tr><th></th><th>Internet</th><th>WWW</th></tr></thead><tbody><tr><td><strong>Là gì</strong></td><td>Hạ tầng – mạng vật lý toàn cầu</td><td>Dịch vụ – hệ thống trang web</td></tr><tr><td><strong>Ví dụ</strong></td><td>Đường cao tốc</td><td>Xe ô tô chạy trên đường</td></tr><tr><td><strong>Không có thì sao</strong></td><td>Không có gì hoạt động</td><td>Web không dùng được, nhưng email, game online vẫn dùng được</td></tr><tr><td><strong>Giao thức</strong></td><td>TCP/IP</td><td>HTTP/HTTPS</td></tr><tr><td><strong>Ra đời</strong></td><td>1969 (ARPANET)</td><td>1991 (Tim Berners-Lee)</td></tr></tbody></table><blockquote><p><strong>Kết luận:</strong> WWW chạy <strong>trên</strong> Internet. Internet tồn tại trước WWW 20 năm.</p></blockquote><h3 id="tai-sao-https-quan-trong" tabindex="-1">Tại sao HTTPS quan trọng? <a class="header-anchor" href="#tai-sao-https-quan-trong" aria-label="Permalink to &quot;Tại sao HTTPS quan trọng?&quot;">​</a></h3><p>Khi bạn đăng nhập ngân hàng qua HTTP (không mã hóa):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Bạn gửi: username=nguyenvana&amp;password=123456</span></span>
<span class="line"><span>Kẻ tấn công (nghe lén): nhìn thấy y chang → đánh cắp được!</span></span></code></pre></div><p>Khi dùng HTTPS (mã hóa TLS):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Bạn gửi: Xd3#kL9@qW7!mN2...  (đã mã hóa)</span></span>
<span class="line"><span>Kẻ tấn công: nhìn thấy chuỗi vô nghĩa → không đọc được gì!</span></span></code></pre></div><hr><h2 id="🔹-4-luong-hoat-đong-step-by-step" tabindex="-1">🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP <a class="header-anchor" href="#🔹-4-luong-hoat-đong-step-by-step" aria-label="Permalink to &quot;🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP&quot;">​</a></h2><h3 id="luong-gui-email-hoan-chinh" tabindex="-1">Luồng gửi email hoàn chỉnh <a class="header-anchor" href="#luong-gui-email-hoan-chinh" aria-label="Permalink to &quot;Luồng gửi email hoàn chỉnh&quot;">​</a></h3><p><strong>Tình huống:</strong> Bạn (dùng Gmail) gửi email cho bạn bè (dùng Outlook/Hotmail).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Bước 1] Bạn soạn email và nhấn &quot;Gửi&quot; trong Gmail (trình duyệt/app)</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 2] Gmail dùng SMTP gửi email đến máy chủ SMTP của Google</span></span>
<span class="line"><span>         (smtp.gmail.com : cổng 587)</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 3] Máy chủ Google → tra DNS để tìm IP máy chủ của Outlook</span></span>
<span class="line"><span>         (MX record của hotmail.com / outlook.com)</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 4] Máy chủ Google → kết nối SMTP → gửi email đến máy chủ Microsoft</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 5] Email được lưu trên máy chủ Microsoft</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 6] Khi bạn bè mở Outlook:</span></span>
<span class="line"><span>         - Nếu dùng IMAP: Đồng bộ, xem trên nhiều thiết bị</span></span>
<span class="line"><span>         - Nếu dùng POP3: Tải về máy và xóa khỏi server</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 7] Bạn bè đọc được email của bạn</span></span></code></pre></div><h3 id="luong-truy-cap-trang-web" tabindex="-1">Luồng truy cập trang web <a class="header-anchor" href="#luong-truy-cap-trang-web" aria-label="Permalink to &quot;Luồng truy cập trang web&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Bước 1] Bạn gõ https://vnexpress.net vào trình duyệt</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 2] Trình duyệt hỏi DNS server: &quot;IP của vnexpress.net là gì?&quot;</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 3] DNS trả lời: &quot;203.162.0.130&quot;</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 4] Trình duyệt kết nối TCP đến 203.162.0.130, cổng 443 (HTTPS)</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 5] SSL/TLS handshake – thiết lập kênh mã hóa</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 6] Trình duyệt gửi HTTP GET request: &quot;Cho tôi trang chủ&quot;</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 7] Máy chủ trả về HTML, CSS, JavaScript, hình ảnh...</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>[Bước 8] Trình duyệt render và hiển thị trang web</span></span></code></pre></div><hr><h2 id="🔹-5-vi-du-minh-hoa" tabindex="-1">🔹 5. VÍ DỤ MINH HỌA <a class="header-anchor" href="#🔹-5-vi-du-minh-hoa" aria-label="Permalink to &quot;🔹 5. VÍ DỤ MINH HỌA&quot;">​</a></h2><h3 id="vi-du-1-–-phan-tich-url" tabindex="-1">Ví dụ 1 – Phân tích URL <a class="header-anchor" href="#vi-du-1-–-phan-tich-url" aria-label="Permalink to &quot;Ví dụ 1 – Phân tích URL&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://www.youtube.com/watch?v=dQw4w9WgXcQ</span></span>
<span class="line"><span></span></span>
<span class="line"><span>https://     → Giao thức (HTTPS – có mã hóa)</span></span>
<span class="line"><span>www          → Subdomain (tên miền phụ)</span></span>
<span class="line"><span>youtube      → Tên miền cấp 2 (Second-level domain)</span></span>
<span class="line"><span>.com         → Tên miền cấp cao (TLD)</span></span>
<span class="line"><span>/watch       → Đường dẫn (path)</span></span>
<span class="line"><span>?v=dQw4w9WgXcQ → Tham số truy vấn (query string)</span></span></code></pre></div><h3 id="vi-du-2-–-nhan-biet-giao-thuc-tu-tinh-huong" tabindex="-1">Ví dụ 2 – Nhận biết giao thức từ tình huống <a class="header-anchor" href="#vi-du-2-–-nhan-biet-giao-thuc-tu-tinh-huong" aria-label="Permalink to &quot;Ví dụ 2 – Nhận biết giao thức từ tình huống&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tình huống</th><th>Giao thức dùng</th></tr></thead><tbody><tr><td>Upload file lên hosting website</td><td>FTP/SFTP</td></tr><tr><td>Gửi email cho giáo viên</td><td>SMTP</td></tr><tr><td>Mở app Gmail trên điện thoại, email đồng bộ nhiều thiết bị</td><td>IMAP</td></tr><tr><td>Truy cập trang web ngân hàng</td><td>HTTPS</td></tr><tr><td>Xem video trên YouTube</td><td>HTTPS (HTTP/2)</td></tr><tr><td>Tra địa chỉ IP của facebook.com</td><td>DNS</td></tr></tbody></table><h3 id="vi-du-3-–-so-sanh-pop3-vs-imap-trong-thuc-te" tabindex="-1">Ví dụ 3 – So sánh POP3 vs IMAP trong thực tế <a class="header-anchor" href="#vi-du-3-–-so-sanh-pop3-vs-imap-trong-thuc-te" aria-label="Permalink to &quot;Ví dụ 3 – So sánh POP3 vs IMAP trong thực tế&quot;">​</a></h3><p><strong>Tình huống:</strong> Bạn dùng email cả trên điện thoại và máy tính.</p><ul><li><strong>Dùng POP3:</strong> Đọc email trên máy tính → email bị tải về máy tính, <strong>không còn trên server</strong> → mở điện thoại → <strong>không thấy email đó nữa</strong>. ❌</li><li><strong>Dùng IMAP:</strong> Đọc email trên máy tính → email vẫn trên server → mở điện thoại → <strong>vẫn thấy</strong> (đã được đánh dấu đã đọc). ✅</li></ul><blockquote><p>Đây là lý do tại sao Gmail và các dịch vụ email hiện đại đều dùng <strong>IMAP</strong> mặc định.</p></blockquote><hr><h2 id="🔹-6-so-sanh-phan-biet" tabindex="-1">🔹 6. SO SÁNH &amp; PHÂN BIỆT <a class="header-anchor" href="#🔹-6-so-sanh-phan-biet" aria-label="Permalink to &quot;🔹 6. SO SÁNH &amp; PHÂN BIỆT&quot;">​</a></h2><h3 id="cac-giao-thuc-email" tabindex="-1">Các giao thức email <a class="header-anchor" href="#cac-giao-thuc-email" aria-label="Permalink to &quot;Các giao thức email&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>SMTP</th><th>POP3</th><th>IMAP</th></tr></thead><tbody><tr><td><strong>Chức năng</strong></td><td>Gửi email</td><td>Nhận email</td><td>Nhận email</td></tr><tr><td><strong>Cổng</strong></td><td>25 / 587</td><td>110 / 995</td><td>143 / 993</td></tr><tr><td><strong>Lưu trên server</strong></td><td>Không áp dụng</td><td>Xóa sau khi tải</td><td>Giữ nguyên</td></tr><tr><td><strong>Nhiều thiết bị</strong></td><td>Không áp dụng</td><td>Không</td><td>Có</td></tr><tr><td><strong>Phù hợp với</strong></td><td>Gửi đi</td><td>1 thiết bị, tiết kiệm dung lượng server</td><td>Nhiều thiết bị</td></tr></tbody></table><h3 id="http-vs-https" tabindex="-1">HTTP vs HTTPS <a class="header-anchor" href="#http-vs-https" aria-label="Permalink to &quot;HTTP vs HTTPS&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>HTTP</th><th>HTTPS</th></tr></thead><tbody><tr><td><strong>Bảo mật</strong></td><td>Không mã hóa</td><td>Mã hóa SSL/TLS</td></tr><tr><td><strong>Cổng</strong></td><td>80</td><td>443</td></tr><tr><td><strong>Tốc độ</strong></td><td>Nhanh hơn</td><td>Chậm hơn một chút (overhead mã hóa)</td></tr><tr><td><strong>SEO</strong></td><td>Điểm thấp hơn</td><td>Google ưu tiên</td></tr><tr><td><strong>Bắt buộc</strong></td><td>Không</td><td>Có (trình duyệt cảnh báo HTTP)</td></tr></tbody></table><hr><h2 id="🔹-7-ghi-nho-nhanh-đi-thi" tabindex="-1">🔹 7. GHI NHỚ NHANH (ĐI THI) <a class="header-anchor" href="#🔹-7-ghi-nho-nhanh-đi-thi" aria-label="Permalink to &quot;🔹 7. GHI NHỚ NHANH (ĐI THI)&quot;">​</a></h2><ul><li>🌐 <strong>Internet</strong> = mạng của các mạng toàn cầu, dùng TCP/IP</li><li>🕸️ <strong>WWW</strong> = dịch vụ trang web chạy trên Internet, dùng HTTP/HTTPS – <strong>không phải Internet</strong></li><li>📧 <strong>SMTP</strong> = <strong>gửi</strong> email (cổng 25/587)</li><li>📥 <strong>POP3</strong> = <strong>nhận</strong> email, tải về xóa server (cổng 110/995)</li><li>📲 <strong>IMAP</strong> = <strong>nhận</strong> email, đồng bộ nhiều thiết bị (cổng 143/993)</li><li>📁 <strong>FTP</strong> = truyền file (cổng 21)</li><li>🔍 <strong>DNS</strong> = dịch tên miền → địa chỉ IP (&quot;danh bạ Internet&quot;)</li><li>🔒 <strong>HTTPS</strong> = HTTP + mã hóa SSL/TLS (cổng 443) → <strong>bảo mật</strong></li><li>🔓 <strong>HTTP</strong> = không mã hóa (cổng 80) → <strong>không bảo mật</strong></li><li>🏷️ <strong>TLD</strong>: <code>.com</code> (thương mại), <code>.edu</code> (giáo dục), <code>.gov</code> (chính phủ), <code>.vn</code> (Việt Nam)</li><li>📮 Cấu trúc email: <code>tên@nhàcungcấp.tld</code> (ví dụ: <code>nguyenvana@gmail.com</code>)</li><li>🔁 Thứ tự tra web: Gõ URL → DNS phân giải → kết nối IP → HTTPS → hiển thị trang</li></ul><hr><h2 id="🔹-8-bai-tap-tu-luyen" tabindex="-1">🔹 8. BÀI TẬP TỰ LUYỆN <a class="header-anchor" href="#🔹-8-bai-tap-tu-luyen" aria-label="Permalink to &quot;🔹 8. BÀI TẬP TỰ LUYỆN&quot;">​</a></h2><h3 id="cau-1-de-đung-hay-sai" tabindex="-1">Câu 1 (Dễ): Đúng hay Sai? <a class="header-anchor" href="#cau-1-de-đung-hay-sai" aria-label="Permalink to &quot;Câu 1 (Dễ): Đúng hay Sai?&quot;">​</a></h3><blockquote><p>&quot;Internet và World Wide Web là hai khái niệm giống nhau, có thể dùng thay thế cho nhau.&quot;</p></blockquote><p><strong>Đáp án: SAI</strong></p><p><strong>Giải thích:</strong> Internet là hạ tầng mạng vật lý toàn cầu (kết nối các máy tính). WWW là <strong>một dịch vụ</strong> chạy trên Internet (hệ thống trang web dùng HTTP/HTTPS). Internet ra đời năm 1969, WWW ra đời năm 1991. Email, FTP, game online cũng chạy trên Internet nhưng không phải WWW.</p><hr><h3 id="cau-2-de-chon-giao-thuc-phu-hop" tabindex="-1">Câu 2 (Dễ): Chọn giao thức phù hợp <a class="header-anchor" href="#cau-2-de-chon-giao-thuc-phu-hop" aria-label="Permalink to &quot;Câu 2 (Dễ): Chọn giao thức phù hợp&quot;">​</a></h3><blockquote><p>Bạn cần gửi file báo cáo lớn (500MB) lên máy chủ hosting. Bạn nên dùng giao thức nào? A. HTTP B. SMTP C. FTP D. DNS</p></blockquote><p><strong>Đáp án: C – FTP</strong></p><p><strong>Giải thích:</strong> FTP (File Transfer Protocol) được thiết kế đặc biệt để <strong>truyền file</strong> giữa máy tính và máy chủ. HTTP dùng để truy cập trang web. SMTP dùng để gửi email (không phù hợp cho file 500MB). DNS chỉ phân giải tên miền.</p><hr><h3 id="cau-3-trung-binh-phan-tich-url" tabindex="-1">Câu 3 (Trung bình): Phân tích URL <a class="header-anchor" href="#cau-3-trung-binh-phan-tich-url" aria-label="Permalink to &quot;Câu 3 (Trung bình): Phân tích URL&quot;">​</a></h3><blockquote><p>Phân tích các thành phần của URL sau: <code>https://hocsinh.edu.vn/tai-lieu/tin-hoc-12?page=3</code></p></blockquote><p><strong>Đáp án:</strong></p><table tabindex="0"><thead><tr><th>Thành phần</th><th>Giá trị</th><th>Ý nghĩa</th></tr></thead><tbody><tr><td>Giao thức</td><td><code>https</code></td><td>HTTP có mã hóa SSL/TLS</td></tr><tr><td>Tên miền</td><td><code>hocsinh.edu.vn</code></td><td>Tên miền giáo dục Việt Nam</td></tr><tr><td>TLD</td><td><code>.vn</code></td><td>Country code Việt Nam</td></tr><tr><td>SLD</td><td><code>.edu</code></td><td>Giáo dục (second level)</td></tr><tr><td>Đường dẫn</td><td><code>/tai-lieu/tin-hoc-12</code></td><td>Thư mục/trang trên server</td></tr><tr><td>Tham số</td><td><code>?page=3</code></td><td>Tham số truy vấn: trang số 3</td></tr></tbody></table><hr><h3 id="cau-4-trung-binh-chon-pop3-hay-imap" tabindex="-1">Câu 4 (Trung bình): Chọn POP3 hay IMAP <a class="header-anchor" href="#cau-4-trung-binh-chon-pop3-hay-imap" aria-label="Permalink to &quot;Câu 4 (Trung bình): Chọn POP3 hay IMAP&quot;">​</a></h3><blockquote><p>Bạn muốn kiểm tra email công việc trên cả điện thoại, máy tính văn phòng, và máy tính xách tay ở nhà. Email cần đồng bộ ở mọi nơi. Bạn nên cấu hình POP3 hay IMAP? Tại sao?</p></blockquote><p><strong>Đáp án: IMAP</strong></p><p><strong>Giải thích:</strong> IMAP giữ email trên server và đồng bộ với tất cả thiết bị. Khi bạn đọc/xóa email trên điện thoại, thay đổi đó phản ánh ngay trên máy tính văn phòng và máy tính ở nhà. POP3 sẽ tải email xuống một thiết bị và xóa khỏi server, khiến các thiết bị khác không nhìn thấy email đó.</p><hr><h3 id="cau-5-van-dung-phan-tich-bao-mat" tabindex="-1">Câu 5 (Vận dụng): Phân tích bảo mật <a class="header-anchor" href="#cau-5-van-dung-phan-tich-bao-mat" aria-label="Permalink to &quot;Câu 5 (Vận dụng): Phân tích bảo mật&quot;">​</a></h3><blockquote><p>Bạn đang dùng Wi-Fi công cộng tại quán cà phê và truy cập trang web ngân hàng. Trang web đó dùng HTTP (không phải HTTPS). Điều gì có thể xảy ra? Bạn nên làm gì?</p></blockquote><p><strong>Đáp án:</strong></p><p><strong>Rủi ro:</strong> Kẻ tấn công có thể dùng kỹ thuật &quot;Man-in-the-Middle&quot; (nghe lén mạng Wi-Fi) để đọc được <strong>tất cả dữ liệu</strong> bạn gửi qua HTTP, bao gồm:</p><ul><li>Tên đăng nhập và mật khẩu</li><li>Số tài khoản ngân hàng</li><li>Mã OTP (nếu truyền qua HTTP)</li></ul><p><strong>Giải pháp:</strong></p><ol><li><strong>Không truy cập</strong> trang web ngân hàng nếu dùng HTTP trên Wi-Fi công cộng.</li><li>Kiểm tra xem URL có bắt đầu bằng <code>https://</code> và có biểu tượng 🔒 không.</li><li>Dùng <strong>mạng di động (4G/5G)</strong> thay vì Wi-Fi công cộng cho giao dịch nhạy cảm.</li><li>Dùng <strong>VPN</strong> để mã hóa thêm một lớp khi dùng Wi-Fi công cộng.</li></ol><hr><h2 id="🔹-9-loi-thuong-gap" tabindex="-1">🔹 9. LỖI THƯỜNG GẶP <a class="header-anchor" href="#🔹-9-loi-thuong-gap" aria-label="Permalink to &quot;🔹 9. LỖI THƯỜNG GẶP&quot;">​</a></h2><h3 id="❌-loi-1-nham-internet-voi-www" tabindex="-1">❌ Lỗi 1: Nhầm Internet với WWW <a class="header-anchor" href="#❌-loi-1-nham-internet-voi-www" aria-label="Permalink to &quot;❌ Lỗi 1: Nhầm Internet với WWW&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Internet là hệ thống trang web toàn cầu.&quot;</p><p><strong>Đúng:</strong> <strong>WWW</strong> (World Wide Web) mới là hệ thống trang web. <strong>Internet</strong> là hạ tầng mạng vật lý kết nối máy tính toàn cầu. WWW chỉ là một trong nhiều dịch vụ chạy trên Internet (cùng với email, FTP, game online...).</p><hr><h3 id="❌-loi-2-nham-smtp-voi-pop3-imap" tabindex="-1">❌ Lỗi 2: Nhầm SMTP với POP3/IMAP <a class="header-anchor" href="#❌-loi-2-nham-smtp-voi-pop3-imap" aria-label="Permalink to &quot;❌ Lỗi 2: Nhầm SMTP với POP3/IMAP&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Tôi dùng SMTP để nhận email.&quot;</p><p><strong>Đúng:</strong> <strong>SMTP chỉ dùng để GỬI email</strong>. Để nhận email, dùng <strong>POP3</strong> (tải về, xóa server) hoặc <strong>IMAP</strong> (đồng bộ nhiều thiết bị).</p><hr><h3 id="❌-loi-3-nghi-ten-mien-va-đia-chi-ip-la-mot" tabindex="-1">❌ Lỗi 3: Nghĩ tên miền và địa chỉ IP là một <a class="header-anchor" href="#❌-loi-3-nghi-ten-mien-va-đia-chi-ip-la-mot" aria-label="Permalink to &quot;❌ Lỗi 3: Nghĩ tên miền và địa chỉ IP là một&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Địa chỉ web của Google là google.com – đó cũng là địa chỉ IP của Google.&quot;</p><p><strong>Đúng:</strong> <code>google.com</code> là <strong>tên miền</strong> – dễ nhớ cho con người. <strong>Địa chỉ IP</strong> của Google là <code>142.250.196.46</code> (hoặc nhiều IP khác). <strong>DNS</strong> làm nhiệm vụ dịch tên miền sang IP khi bạn truy cập web.</p><hr><h3 id="❌-loi-4-nghi-http-va-https-chi-khac-nhau-ve-bao-mat-khong-khac-cong" tabindex="-1">❌ Lỗi 4: Nghĩ HTTP và HTTPS chỉ khác nhau về bảo mật, không khác cổng <a class="header-anchor" href="#❌-loi-4-nghi-http-va-https-chi-khac-nhau-ve-bao-mat-khong-khac-cong" aria-label="Permalink to &quot;❌ Lỗi 4: Nghĩ HTTP và HTTPS chỉ khác nhau về bảo mật, không khác cổng&quot;">​</a></h3><p><strong>Sai:</strong> &quot;HTTP và HTTPS dùng cùng cổng 80.&quot;</p><p><strong>Đúng:</strong> HTTP dùng <strong>cổng 80</strong>, HTTPS dùng <strong>cổng 443</strong>. Đây là hai cổng khác nhau. Máy chủ web phải mở đúng cổng để nhận kết nối từ trình duyệt.</p><hr><h3 id="❌-loi-5-nham-tld-edu-vn-va-com" tabindex="-1">❌ Lỗi 5: Nhầm TLD .edu.vn và .com <a class="header-anchor" href="#❌-loi-5-nham-tld-edu-vn-va-com" aria-label="Permalink to &quot;❌ Lỗi 5: Nhầm TLD .edu.vn và .com&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Website trường học Việt Nam phải dùng tên miền .edu&quot;</p><p><strong>Đúng:</strong> Ở Việt Nam, website trường học và tổ chức giáo dục dùng tên miền <strong>.edu.vn</strong> (ví dụ: <code>hust.edu.vn</code>, <code>neu.edu.vn</code>). Đây là tên miền quốc gia cấp 2 của Việt Nam. Tên miền <code>.edu</code> (không có <code>.vn</code>) dành cho các tổ chức giáo dục của Mỹ (như <code>harvard.edu</code>).</p>`,137)])])}const u=n(i,[["render",o]]);export{p as __pageData,u as default};
